/* legacy.css, loaded earlier */
#sidebar a {
  color: #555; /* 1-0-1 */
}

/* "more classes will beat it": 0-4-0, still grey */
.app .sidebar .btn.btn-primary {
  color: white;
}

/* "fixed", until the next override needs one too */
.btn-primary {
  color: white !important;
}

@layer legacy, components;

@layer legacy {
  #sidebar a {
    color: #555;
  }
}

@layer components {
  .btn-primary {
    color: white; /* 0-1-0, wins: later layer */
  }
}
